 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, color, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new THREE.Group();

  const visual = config.intent?.visualSpec ?? config.visual ?? {};
  const palette = visual.colors ?? config.colors ?? {};
  const typography = visual.typography ?? config.typography ?? {};
  const items = config.textContent ?? visual.textContent ?? [];

  const bgHex = palette.background ?? '#0b0b10';
  const surfaceHex = palette.surface ?? '#14141a';
  const accentHex = palette.accent ?? '#ff2a38';
  const paperHex = palette.paper ?? '#e8ecf2';
  const inkHex = palette.ink ?? '#16161d';

  const heroPx = typography.hero?.fontSize ?? 124;
  const emScale = 0.62 / heroPx;

  // --- backdrop plate: 7 x 5.5, vertical gradient + 1.5% grain ---
  const noiseData = new Uint8Array(256 * 256);
  for (let i = 0; i < noiseData.length; i++) noiseData[i] = Math.floor(Math.random() * 256);
  const noiseTex = new THREE.DataTexture(noiseData, 256, 256, THREE.RedFormat);
  noiseTex.wrapS = THREE.RepeatWrapping;
  noiseTex.wrapT = THREE.RepeatWrapping;
  noiseTex.needsUpdate = true;

  const bgNode = color(bgHex);
  const surfaceNode = color(surfaceHex);
  const gradT = uv().y;
  const gradient = mix(surfaceNode, bgNode, gradT);
  const grainUV = uv().mul(vec2(512, 512));
  const grainSample = texture(noiseTex, grainUV).r;
  const grain = grainSample.sub(0.5).mul(0.015);
  const plateColor = gradient.add(vec3(grain));

  const plateGeo = new THREE.PlaneGeometry(7, 5.5);
  const plateMat = new MeshBasicNodeMaterial({ colorNode: plateColor });
  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, 0);
  root.add(plate);

  // --- accent underline rule ---
  const ruleWrap = new THREE.Group();
  ruleWrap.position.set(-3.1, -0.15, 0.05);
  ruleWrap.scale.x = 0;
  const ruleGeo = new THREE.PlaneGeometry(2.2, 0.05);
  ruleGeo.translate(1.1, 0, 0);
  const accentNode = color(accentHex);
  const ruleMat = new MeshBasicNodeMaterial({ colorNode: accentNode.mul(1.2) });
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  ruleWrap.add(rule);
  root.add(ruleWrap);

  // --- text builder ---
  const tl = gsap.timeline();
  const timelineHandles = [tl];
  const allMaterials = [];

  function gatherMaterials(obj, list) {
    obj.traverse((child) => {
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => {
          m.transparent = true;
          m.needsUpdate = true;
          list.push(m);
        });
      }
    });
  }

  function getFontSize(item) {
    return (item.typography?.fontSize ?? heroPx) * emScale;
  }

  function addTextBlock(item, y, startAt) {
    const fontSize = getFontSize(item);
    const tracking = item.typography?.letterSpacing ?? 0;
    const wrap = new THREE.Group();
    wrap.position.set(-3.1, y + 0.4, 0.05);

    const opts = {
      fontSize,
      color: paperHex,
      align: 'left',
      letterSpacingPx: fontSize * tracking,
      maxWidthPx: item.role === 'body' ? 4.5 : undefined,
    };

    const text = ctx.fontAtlas.createText(item.text, opts);
    wrap.add(text);

    if (item.role === 'hero') {
      const shadow = ctx.fontAtlas.createText(item.text, { ...opts, color: inkHex });
      shadow.position.z = -0.02;
      wrap.add(shadow);
    }

    const mats = [];
    gatherMaterials(wrap, mats);
    allMaterials.push(...mats);
    root.add(wrap);

    mats.forEach((m) => { m.opacity = 0; });

    const opacityProxy = { value: 0 };
    tl.to(
      wrap.position,
      { y, duration: 0.7, ease: 'power3.out' },
      startAt
    );
    tl.to(
      opacityProxy,
      {
        value: 1,
        duration: 0.7,
        ease: 'power3.out',
        onUpdate: () => {
          mats.forEach((m) => { m.opacity = opacityProxy.value; });
        },
      },
      startAt
    );
  }

  // Layout order: kicker, hero lines, rule, body, caption
  const kickerItem = items.find((i) => i.role === 'kicker');
  const heroItems = items.filter((i) => i.role === 'hero');
  const bodyItem = items.find((i) => i.role === 'body');
  const captionItem = items.find((i) => i.role === 'caption');

  if (kickerItem) addTextBlock(kickerItem, 1.7, 0);
  heroItems.slice(0, 2).forEach((it, idx) => {
    const y = idx === 0 ? 0.9 : 0.25;
    addTextBlock(it, y, 0.08 + idx * 0.08);
  });

  tl.to(
    ruleWrap.scale,
    { x: 1, duration: 0.5, ease: 'power2.out' },
    0.86
  );

  if (bodyItem) addTextBlock(bodyItem, -0.8, 0.24);
  if (captionItem) addTextBlock(captionItem, -1.9, 0.32);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    timelineHandles.forEach((t) => t.kill && t.kill());
    root.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
    noiseTex.dispose();
  };

  return root;
}
